/*
  ABI Configuration file for the Fast Light Tool Kit (FLTK).

  Normally generated by configure/CMake from abi-version.in. Hand-provided
  here for the no-configure Dev-C++ build (build_fltk.bat). Leaving
  FL_ABI_VERSION undefined makes FL/Enumerations.H fall back to the default
  stable ABI (FL_MAJOR*10000 + FL_MINOR*100 = 10300), which is the standard
  configure output when --with-abiversion is not passed.
*/

#undef FL_ABI_VERSION
